/**
 * Tokenizer module for converting various input types to standardized tokens.
 *
 * This Scala translation follows functional programming idioms and leverages:
 * - Sealed algebraic data types for TokenType
 * - Immutable case classes for Token
 * - Generic traits with variance annotations
 * - Type classes for extensibility
 * - Iterator/Seq for lazy and eager evaluation
 * - Either/Option for error handling
 *
 * Scala 2.13 compatible
 */

import scala.collection.immutable._
import scala.math.BigDecimal
import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import java.util.regex.Pattern
import scala.reflect.ClassTag
import scala.util.{Try, Using}

// ============================================================================
// Type Level Definitions and Protocols
// ============================================================================

/**
 * Type class for values that can be converted to a token string.
 */
trait Tokenizable {
  def toToken: String
}

/**
 * Type class for processable values.
 * Demonstrates contravariance: processors can handle supertypes
 */
trait TokenProcessor[-T] {
  def process(item: T): Unit
}

/**
 * Type class for values with a length.
 */
trait HasLength {
  def len: Int
}

// ============================================================================
// Token Type and Token Implementation
// ============================================================================

/**
 * Sealed algebraic data type for token categories.
 * Using sealed allows exhaustive pattern matching.
 */
sealed trait TokenType {
  def value: String
}

object TokenType {
  case object String extends TokenType { val value = "string" }
  case object Numeric extends TokenType { val value = "numeric" }
  case object Temporal extends TokenType { val value = "temporal" }
  case object Structured extends TokenType { val value = "structured" }
  case object Binary extends TokenType { val value = "binary" }
  case object Null extends TokenType { val value = "null" }

  def fromString(s: String): Option[TokenType] = s match {
    case "string" => Some(String)
    case "numeric" => Some(Numeric)
    case "temporal" => Some(Temporal)
    case "structured" => Some(Structured)
    case "binary" => Some(Binary)
    case "null" => Some(Null)
    case _ => None
  }
}

/**
 * Immutable token representation with metadata support.
 */
final case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {
  /**
   * Returns a new token with additional metadata merged.
   */
  def withMetadata(additions: (String, Any)*): Token =
    copy(metadata = metadata ++ additions.toMap)

  /**
   * Safely retrieves metadata value.
   */
  def getMetadata[A](key: String): Option[A] =
    metadata.get(key).asInstanceOf[Option[A]]

  override def toString: String =
    s"Token($value, ${tokenType.value}, ${metadata.filterKeys(_ != "original").mkString("{", ", ", "}")})"
}

// ============================================================================
// Mutable Token Batch (contrast with immutable Token)
// ============================================================================

/**
 * Mutable batch collection for accumulating tokens.
 * Useful for incremental tokenization in imperative contexts.
 */
class TokenBatch {
  private val tokens: scala.collection.mutable.ListBuffer[Token] =
    scala.collection.mutable.ListBuffer.empty
  @volatile private var processed: Boolean = false

  def add(token: Token): TokenBatch = {
    if (processed) {
      throw new IllegalStateException("Batch already processed")
    }
    tokens += token
    this
  }

  def addAll(ts: Iterable[Token]): TokenBatch = {
    if (processed) {
      throw new IllegalStateException("Batch already processed")
    }
    tokens ++= ts
    this
  }

  def markProcessed(): Unit = {
    processed = true
  }

  def toList: List[Token] = tokens.toList

  def toVector: Vector[Token] = tokens.toVector

  def size: Int = tokens.size

  def isEmpty: Boolean = tokens.isEmpty
}

// ============================================================================
// Generic Containers with Variance
// ============================================================================

/**
 * Covariant container - can return subtypes.
 * The +T variance allows this to be a subtype of TokenContainer[Supertype]
 */
sealed class TokenContainer[+T](private val items: Vector[T]) {
  def getAll: Vector[T] = items

  def size: Int = items.size

  def isEmpty: Boolean = items.isEmpty

  def map[U](f: T => U): TokenContainer[U] =
    new TokenContainer(items.map(f))

  def mapTokens(f: T => String): List[String] =
    items.map(f).toList

  def foreach(f: T => Unit): Unit =
    items.foreach(f)

  def iterator: Iterator[T] = items.iterator
}

object TokenContainer {
  def apply[T](items: T*): TokenContainer[T] =
    new TokenContainer(Vector(items: _*))

  def from[T](items: Iterable[T]): TokenContainer[T] =
    new TokenContainer(items.toVector)

  def empty[T]: TokenContainer[T] =
    new TokenContainer[T](Vector.empty)
}

/**
 * Contravariant sink - can accept supertypes.
 * The -T variance allows this to accept supertypes.
 */
sealed class TokenSink[-T] {
  private val received: scala.collection.mutable.ListBuffer[Any] =
    scala.collection.mutable.ListBuffer.empty

  def receive(item: T): TokenSink[T] = {
    received += item.asInstanceOf[Any]
    this
  }

  def receiveAll(items: Iterable[T]): TokenSink[T] = {
    received ++= items
    this
  }

  def drain(): List[Any] = {
    val result = received.toList
    received.clear()
    result
  }

  def size: Int = received.size
}

object TokenSink {
  def apply[T]: TokenSink[T] = new TokenSink[T]()
}

/**
 * Invariant handler - exact type matching required.
 * Using T (neither covariant nor contravariant) for both get and set.
 */
final class BivariantHandler[T](initialValue: T) {
  private var value: T = initialValue

  def get: T = value

  def set(newValue: T): Unit = {
    value = newValue
  }

  def transform(f: T => T): T = {
    value = f(value)
    value
  }

  def map[U](f: T => U): U = f(value)
}

// ============================================================================
// Base Tokenizer Trait and Implementations
// ============================================================================

/**
 * Abstract base tokenizer trait with generic input type.
 * Provides both eager (tokenize) and lazy (tokenizeIterator) interfaces.
 */
trait BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeIterator(values: Iterator[T]): Iterator[Token] =
    values.map(tokenize)

  def tokenizeBatch(values: Iterable[T]): Seq[Token] =
    values.map(tokenize).toSeq

  def tokenizeOption(value: Option[T]): Option[Token] =
    value.map(tokenize)

  def tokenizeEither[E](value: Either[E, T]): Either[E, Token] =
    value.map(tokenize)
}

/**
 * Tokenizer for string and bytes types.
 * Supports encoding conversion and optional normalization.
 */
final class StringTokenizer(
    encoding: String = "UTF-8",
    normalizer: String => String = identity
) extends BaseTokenizer[String] {

  def tokenize(value: String): Token = {
    val normalized = normalizer(value)
    Token(normalized, TokenType.String)
  }

  def tokenizeBytes(value: Array[Byte]): Token = {
    val str = new String(value, encoding)
    tokenize(str)
  }

  def withNormalizer(f: String => String): StringTokenizer =
    new StringTokenizer(encoding, f.compose(normalizer))

  def withEncoding(enc: String): StringTokenizer =
    new StringTokenizer(enc, normalizer)
}

/**
 * Numeric tokenizer with precision handling.
 * Supports Int, Long, Double, Float, and BigDecimal.
 */
final class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Number] {

  def tokenize(value: Number): Token = {
    val stringValue = value match {
      case bd: BigDecimal => f"${bd.doubleValue}%.${precision}f"
      case d: Double => f"$d%.${precision}f"
      case f: Float => f"${f.toDouble}%.${precision}f"
      case i: Int => i.toString
      case l: Long => l.toString
      case _ => value.toString
    }

    Token(
      stringValue,
      TokenType.Numeric,
      Map("original_type" -> value.getClass.getSimpleName)
    )
  }

  def withPrecision(p: Int): NumericTokenizer =
    new NumericTokenizer(p, formatOptions)
}

/**
 * Temporal tokenizer for date/time types.
 * Supports LocalDate and LocalDateTime with configurable formats.
 */
final class TemporalTokenizer(
    customFormat: Option[String] = None
) extends BaseTokenizer[java.time.temporal.Temporal] {

  private val isoFormat = DateTimeFormatter.ISO_DATE_TIME
  private val dateFormat = DateTimeFormatter.ISO_DATE
  private val customFormatter =
    customFormat.map(DateTimeFormatter.ofPattern(_))

  def tokenize(value: java.time.temporal.Temporal): Token = {
    val formatter = (value, customFormatter) match {
      case (_, Some(cf)) => cf
      case (_: LocalDateTime, _) => isoFormat
      case (_: LocalDate, _) => dateFormat
      case _ => isoFormat
    }

    val stringValue = formatter.format(value)
    Token(stringValue, TokenType.Temporal)
  }

  def withFormat(fmt: String): TemporalTokenizer =
    new TemporalTokenizer(Some(fmt))
}

// ============================================================================
// Universal Tokenizer with Polymorphic Dispatch
// ============================================================================

/**
 * Tokenizer that handles multiple types through type class instances.
 * This is more idiomatic than Python's runtime type checking.
 */
final class UniversalTokenizer(
    private val stringTokenizer: StringTokenizer = new StringTokenizer,
    private val numericTokenizer: NumericTokenizer = new NumericTokenizer,
    private val temporalTokenizer: TemporalTokenizer = new TemporalTokenizer
) {

  def tokenize[T](value: T): Token = {
    value match {
      case null => Token("NULL", TokenType.Null)
      case t: Tokenizable => Token(t.toToken, TokenType.Structured)
      case s: String => stringTokenizer.tokenize(s)
      case b: Array[Byte] => stringTokenizer.tokenizeBytes(b)
      case n: Number => numericTokenizer.tokenize(n)
      case d: LocalDate => temporalTokenizer.tokenize(d)
      case dt: LocalDateTime => temporalTokenizer.tokenize(dt)
      case _ =>
        // Fallback: convert to string
        Token(value.toString, TokenType.String, Map("fallback" -> true))
    }
  }

  def tokenizeSeq[T](values: Seq[T]): Seq[Token] =
    values.map(tokenize)

  def tokenizeIterator[T](values: Iterator[T]): Iterator[Token] =
    values.map(tokenize)

  def withStringTokenizer(st: StringTokenizer): UniversalTokenizer =
    new UniversalTokenizer(st, numericTokenizer, temporalTokenizer)

  def withNumericTokenizer(nt: NumericTokenizer): UniversalTokenizer =
    new UniversalTokenizer(stringTokenizer, nt, temporalTokenizer)

  def withTemporalTokenizer(tt: TemporalTokenizer): UniversalTokenizer =
    new UniversalTokenizer(stringTokenizer, numericTokenizer, tt)
}

// ============================================================================
// Token Registry with Generic Handling
// ============================================================================

/**
 * Registry with complex generic handling.
 * Maintains containers and handlers for incremental token processing.
 */
final class TokenRegistry[T] {
  private val registryMap: scala.collection.mutable.Map[String, TokenContainer[T]] =
    scala.collection.mutable.Map.empty

  private val handlers: scala.collection.mutable.ListBuffer[T => Option[Token]] =
    scala.collection.mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[T]): TokenRegistry[T] = {
    registryMap(key) = container
    this
  }

  def addHandler(handler: T => Option[Token]): TokenRegistry[T] = {
    handlers += handler
    this
  }

  def process(key: String): List[Option[Token]] = {
    registryMap.get(key) match {
      case Some(container) =>
        container.getAll.map { item =>
          handlers.iterator.map(_(item)).find(_.isDefined).flatten
        }.toList
      case None => List.empty
    }
  }

  def getContainer(key: String): Option[TokenContainer[T]] =
    registryMap.get(key)

  def getHandler(index: Int): Option[T => Option[Token]] =
    if (index >= 0 && index < handlers.size) Some(handlers(index))
    else None
}

object TokenRegistry {
  def apply[T]: TokenRegistry[T] = new TokenRegistry[T]()
}

// ============================================================================
// Functional Container with Monad-like Operations
// ============================================================================

/**
 * Functor for tokens supporting map and flatMap operations.
 * Provides a more functional approach to token transformation.
 */
sealed trait TokenFunctor[+T] {
  def map[U](f: T => U): TokenFunctor[U]

  def flatMap[U](f: T => TokenFunctor[U]): TokenFunctor[U]

  def getOrElse[U >: T](default: U): U

  def foreach(f: T => Unit): Unit

  def toOption: Option[T]
}

final case class TokenValue[T](value: T) extends TokenFunctor[T] {
  def map[U](f: T => U): TokenFunctor[U] =
    TokenValue(f(value))

  def flatMap[U](f: T => TokenFunctor[U]): TokenFunctor[U] =
    f(value)

  def getOrElse[U >: T](default: U): U =
    value

  def foreach(f: T => Unit): Unit =
    f(value)

  def toOption: Option[T] = Some(value)
}

final case class TokenEmpty[T]() extends TokenFunctor[T] {
  def map[U](f: T => U): TokenFunctor[U] =
    TokenEmpty()

  def flatMap[U](f: T => TokenFunctor[U]): TokenFunctor[U] =
    TokenEmpty()

  def getOrElse[U >: T](default: U): U =
    default

  def foreach(f: T => Unit): Unit = ()

  def toOption: Option[T] = None
}

object TokenFunctor {
  def pure[T](value: T): TokenFunctor[T] = TokenValue(value)

  def empty[T]: TokenFunctor[T] = TokenEmpty()

  def fromOption[T](opt: Option[T]): TokenFunctor[T] =
    opt.fold[TokenFunctor[T]](TokenEmpty())(TokenValue(_))
}

/**
 * Monad operations extended from TokenFunctor.
 */
sealed trait TokenMonad[+T] extends TokenFunctor[T] {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U]
}

final case class TokenMonadValue[T](value: T) extends TokenMonad[T] {
  def map[U](f: T => U): TokenMonad[U] =
    TokenMonadValue(f(value))

  def flatMap[U](f: T => TokenFunctor[U]): TokenFunctor[U] =
    f(value) match {
      case m: TokenMonad[U] => m
      case v: TokenValue[U] => v
      case _ => TokenEmpty()
    }

  def getOrElse[U >: T](default: U): U =
    value

  def foreach(f: T => Unit): Unit =
    f(value)

  def toOption: Option[T] = Some(value)

  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] =
    funcWrapped match {
      case TokenMonadValue(f) => TokenMonadValue(f(value))
      case _ => TokenMonadEmpty()
    }
}

final case class TokenMonadEmpty[T]() extends TokenMonad[T] {
  def map[U](f: T => U): TokenMonad[U] =
    TokenMonadEmpty()

  def flatMap[U](f: T => TokenFunctor[U]): TokenFunctor[U] =
    TokenMonadEmpty()

  def getOrElse[U >: T](default: U): U =
    default

  def foreach(f: T => Unit): Unit = ()

  def toOption: Option[T] = None

  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] =
    TokenMonadEmpty()
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = TokenMonadValue(value)

  def empty[T]: TokenMonad[T] = TokenMonadEmpty()
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

/**
 * Type alias for JSON values with recursive definition.
 * Uses a sealed trait to properly model the recursive structure.
 */
sealed trait JsonValue

object JsonValue {
  case object JsonNull extends JsonValue
  final case class JsonString(s: String) extends JsonValue
  final case class JsonNumber(n: Double) extends JsonValue
  final case class JsonBoolean(b: Boolean) extends JsonValue
  final case class JsonArray(elements: Vector[JsonValue]) extends JsonValue
  final case class JsonObject(fields: Map[String, JsonValue]) extends JsonValue

  def fromAny(value: Any): JsonValue = value match {
    case null => JsonNull
    case s: String => JsonString(s)
    case n: Number => JsonNumber(n.doubleValue())
    case b: Boolean => JsonBoolean(b)
    case a: Iterable[_] => JsonArray(a.map(fromAny).toVector)
    case m: Map[_, _] =>
      JsonObject(
        m.asInstanceOf[Map[String, Any]].mapValues(fromAny).toMap
      )
    case _ => JsonString(value.toString)
  }
}

/**
 * Tokenizer for JSON structures with path extraction support.
 */
final class JsonTokenizer(pretty: Boolean = false) {

  def tokenize(value: JsonValue): Token = {
    val stringValue = if (pretty) prettyPrint(value) else compactPrint(value)
    Token(stringValue, TokenType.Structured, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.")
    extractPath(value, parts).map(tokenize)
  }

  private def extractPath(
      current: JsonValue,
      parts: Array[String],
      index: Int = 0
  ): Option[JsonValue] = {
    if (index >= parts.length) return Some(current)

    val part = parts(index)
    current match {
      case JsonValue.JsonObject(fields) =>
        fields.get(part).flatMap(extractPath(_, parts, index + 1))
      case JsonValue.JsonArray(elements) =>
        Try(part.toInt)
          .toOption
          .filter(i => i >= 0 && i < elements.size)
          .flatMap(i => extractPath(elements(i), parts, index + 1))
      case _ => None
    }
  }

  private def compactPrint(value: JsonValue): String = value match {
    case JsonValue.JsonNull => "null"
    case JsonValue.JsonString(s) => s""""$s""""
    case JsonValue.JsonNumber(n) => n.toString
    case JsonValue.JsonBoolean(b) => b.toString
    case JsonValue.JsonArray(elements) =>
      elements.map(compactPrint).mkString("[", ",", "]")
    case JsonValue.JsonObject(fields) =>
      fields
        .map { case (k, v) => s""""$k":${compactPrint(v)}""" }
        .mkString("{", ",", "}")
  }

  private def prettyPrint(value: JsonValue, indent: Int = 0): String = {
    val indentStr = " " * (indent * 2)
    val nextIndentStr = " " * ((indent + 1) * 2)

    value match {
      case JsonValue.JsonNull => "null"
      case JsonValue.JsonString(s) => s""""$s""""
      case JsonValue.JsonNumber(n) => n.toString
      case JsonValue.JsonBoolean(b) => b.toString
      case JsonValue.JsonArray(elements) =>
        if (elements.isEmpty) "[]"
        else {
          val items = elements
            .map(e => s"$nextIndentStr${prettyPrint(e, indent + 1)}")
            .mkString(",\n")
          s"[\n$items\n$indentStr]"
        }
      case JsonValue.JsonObject(fields) =>
        if (fields.isEmpty) "{}"
        else {
          val items = fields
            .map { case (k, v) =>
              s"""$nextIndentStr"$k": ${prettyPrint(v, indent + 1)}"""
            }
            .mkString(",\n")
          s"{\n$items\n$indentStr}"
        }
    }
  }
}

// ============================================================================
// Whitespace Tokenizer - Practical Text Tokenization
// ============================================================================

/**
 * Tokenizer that splits text by whitespace.
 * Core functionality for NLP and text processing applications.
 * Supports options for case normalization, length filtering, and punctuation removal.
 */
final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {

  private val punctuationPattern: Pattern =
    Pattern.compile("[.,!?;:'\"\\'\\[\\](){}]")

  def tokenize(text: String): Seq[Token] = {
    text.split("\\s+").zipWithIndex.flatMap { case (word, idx) =>
      processToken(word).map { processed =>
        Token(
          processed,
          TokenType.String,
          Map("position" -> idx, "original" -> word)
        )
      }
    }.toSeq
  }

  def tokenizeToStrings(text: String): Seq[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): Seq[(String, Int, Int)] = {
    var currentPos = 0
    text.split("\\s+").flatMap { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length
      currentPos = end

      processToken(word).map { processed =>
        (processed, start, end)
      }
    }.toSeq
  }

  def countTokens(text: String): Int =
    tokenize(text).length

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = punctuationPattern.matcher(processed).replaceAll("")
    }

    if (processed.isEmpty) return None

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) return None

    if (maxLength.exists(processed.length > _)) {
      processed = processed.take(maxLength.get)
    }

    if (processed.isEmpty) None else Some(processed)
  }
}

object WhitespaceTokenizer {
  def apply(
      lowercase: Boolean = false,
      minLength: Int = 0,
      maxLength: Option[Int] = None,
      stripPunctuation: Boolean = false
  ): WhitespaceTokenizer =
    new WhitespaceTokenizer(lowercase, minLength, maxLength, stripPunctuation)

  /**
   * Factory for common configurations
   */
  object Defaults {
    val basic: WhitespaceTokenizer = WhitespaceTokenizer()
    val lowercase: WhitespaceTokenizer = WhitespaceTokenizer(lowercase = true)
    val noPunctuation: WhitespaceTokenizer =
      WhitespaceTokenizer(stripPunctuation = true)
    val lowercaseNoPunctuation: WhitespaceTokenizer =
      WhitespaceTokenizer(lowercase = true, stripPunctuation = true)
  }
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating custom tokenizers.
 * Supports chaining operations with type-safe method returns.
 */
final class TokenizerBuilder[T] {
  private var normalizers: List[String => String] = List.empty
  private var validators: List[T => Boolean] = List.empty
  private var meta: Map[String, Any] = Map.empty

  def withNormalizer(f: String => String): TokenizerBuilder[T] = {
    normalizers = normalizers :+ f
    this
  }

  def withValidator(f: T => Boolean): TokenizerBuilder[T] = {
    validators = validators :+ f
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] = {
    meta = meta ++ entries.toMap
    this
  }

  def addNormalizers(fs: String => String*): TokenizerBuilder[T] = {
    normalizers = normalizers ++ fs
    this
  }

  def addValidators(fs: (T => Boolean)*): TokenizerBuilder[T] = {
    validators = validators ++ fs
    this
  }

  /**
   * Builds a tokenizer function from accumulated configuration.
   */
  def build(): T => Token = { value =>
    // Validate
    validators.foreach { validator =>
      if (!validator(value)) {
        throw new IllegalArgumentException(s"Validation failed for: $value")
      }
    }

    // Convert to string
    var stringValue = value.toString

    // Apply normalizers
    stringValue = normalizers.foldLeft(stringValue) { (s, f) => f(s) }

    Token(stringValue, TokenType.String, meta)
  }

  /**
   * Builds a safe tokenizer that returns Try[Token].
   */
  def buildSafe(): T => Try[Token] = { value =>
    Try {
      validators.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for: $value")
        }
      }

      var stringValue = value.toString
      stringValue = normalizers.foldLeft(stringValue) { (s, f) => f(s) }

      Token(stringValue, TokenType.String, meta)
    }
  }

  /**
   * Builds a validated tokenizer returning Either[String, Token].
   */
  def buildValidated(): T => Either[String, Token] = { value =>
    validators.find(!_(value)) match {
      case Some(_) =>
        Left(s"Validation failed for: $value")
      case None =>
        val stringValue = normalizers.foldLeft(value.toString) { (s, f) =>
          f(s)
        }
        Right(Token(stringValue, TokenType.String, meta))
    }
  }
}

object TokenizerBuilder {
  def apply[T]: TokenizerBuilder[T] = new TokenizerBuilder[T]()
}

// ============================================================================
// Utility Functions
// ============================================================================

/**
 * Top-level tokenization functions for convenient access.
 */
object Tokenizers {

  /**
   * Tokenize a single value using the universal tokenizer.
   */
  def tokenize[T](value: T): Token = {
    val ut = new UniversalTokenizer()
    ut.tokenize(value)
  }

  /**
   * Batch tokenize multiple values.
   */
  def tokenizeBatch[T](values: Seq[T]): Seq[Token] = {
    val ut = new UniversalTokenizer()
    ut.tokenizeSeq(values)
  }

  /**
   * Lazy tokenization via iterator.
   */
  def tokenizeIterator[T](values: Iterator[T]): Iterator[Token] = {
    val ut = new UniversalTokenizer()
    ut.tokenizeIterator(values)
  }

  /**
   * Create a Token with metadata.
   */
  def toToken(
      value: String,
      tpe: TokenType,
      metadata: (String, Any)*
  ): Token =
    Token(value, tpe, metadata.toMap)

  /**
   * Create Token with metadata using a builder style.
   */
  def tokenWithMetadata(value: String, tpe: TokenType): TokenBuilder =
    TokenBuilder(value, tpe)

  final case class TokenBuilder(value: String, tpe: TokenType) {
    private var meta: Map[String, Any] = Map.empty

    def withMeta(entries: (String, Any)*): TokenBuilder = {
      meta = meta ++ entries.toMap
      this
    }

    def build: Token = Token(value, tpe, meta)
  }
}

/**
 * Implicit conversion helpers for ergonomic usage.
 */
object TokenizerImplicits {
  implicit class StringTokenizerOps(s: String) {
    def tokenize: Token = Tokenizers.tokenize(s)

    def tokenizeWhitespace: Seq[Token] =
      WhitespaceTokenizer.Defaults.basic.tokenize(s)

    def tokenizeWords: Seq[String] =
      WhitespaceTokenizer.Defaults.basic.tokenizeToStrings(s)
  }

  implicit class NumberTokenizerOps[N <: Number](n: N) {
    def tokenize: Token = Tokenizers.tokenize(n)
  }
}

